  Lemma seg_H3s : ltac2:(zQ "hb0!j7!q0!ik2!jje!nof!kvb!hif!ihf!ip8!h8!iq0!irf!nt4!ogb!oja!vgd!ok3!vh7!vi1!via!or6!os2!osa!pgc!pl8!pu1!puc>4vals@1$9@1$1@1$0#k0>1R@2$e@1$0#5@1$1@1$0#k0>1M>0@1$1@1$0#k0@1$b@1$1@1$0#8>3msF$4>2mo$d>0@3$2$a@2$8@1$1@1$0#k0^5Nhk3>0@3$2@1$1@1$0#k0@2$6^6N0?3sp0>0@3$2@1$1@1$0#k0@2$6^7Nb@2$7@1$0#k0+2>0@3$ha@1$5^8$h3^7>0@4$h9$3@1$5^9^7$h1>0@3$h0^7^6^8>0@3$2$4@3$h4?1L?1S^8@5$h5?2fx^a@2$7@1$0#k0@1$f$h2^9@1$h6$3@4$h8$3$h7@2$c^9^8?1K").
