    rewrite msg_usage_eq. rewrite app_assoc. unfold W.
    lazymatch goal with |- realizes _ (mkCfg ?msFc ?moc) _ =>
    apply (stdio_call_sound_post vals (blobs_ev []) srG3s knG3s R' M' L S Zr msFc moc scG3s (PRE17 ++ path) SUF7
